class SoundPlayer extends HTMLElement {
    constructor() {
        super();
        this.attachShadow({ mode: 'open' });
        this.src = this.getAttribute('src');
        
        this.shadowRoot.innerHTML = `
            <audio id="audio-player" src="${this.src}"></audio>
        `;
        this.audioElement = this.shadowRoot.getElementById('audio-player');
    }

    // Método público para reproducir el sonido
    play() {
        if (this.audioElement) {
            this.audioElement.play().catch(error => console.error("Error playing sound:", error));
        }
    }

    // Método público para detener el sonido
    stop() {
        if (this.audioElement) {
            this.audioElement.pause();
            this.audioElement.currentTime = 0;
        }
    }

    // Observa cambios en el atributo 'src'
    attributeChangedCallback(name, oldValue, newValue) {
        if (name === 'src' && this.audioElement) {
            this.audioElement.src = newValue;
        }
    }

    static get observedAttributes() {
        return ['src'];
    }
}

customElements.define('sound-player', SoundPlayer);
